function injectMobileNavStyle(){
if(document.getElementById("gp-mobile-nav-style"))return;
const st=document.createElement("style");st.id="gp-mobile-nav-style";
st.textContent=`body .logo-img{border-radius:0}
@media (max-width:860px){
:root{--gp-glow:0 0 0 1px rgba(226,35,58,.16),0 0 14px rgba(226,35,58,.5),0 0 38px rgba(226,35,58,.28),0 12px 30px -10px rgba(20,10,12,.28)}
/* floating pill */
body .nav,body .nav.is-scrolled{top:calc(12px + env(safe-area-inset-top,0px));left:0;right:0;margin:0 auto;width:clamp(204px,56vw,236px);padding:7px 8px 7px 14px;border:1.5px solid var(--red);border-radius:100px;background:#fff;-webkit-backdrop-filter:none;backdrop-filter:none;box-shadow:var(--gp-glow);transition:opacity .25s var(--ease),visibility .25s}
body .nav .logo-img{height:28px;max-width:130px;object-fit:contain}
body .nav-toggle{width:36px;height:36px;flex:0 0 36px;gap:5px;padding:0}
body .nav-toggle span{width:20px}
body.nav-lock .nav{opacity:0;visibility:hidden;pointer-events:none}
body .nav-backdrop{background:rgba(20,14,15,.5);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
/* expanded card */
body .nav-panel{top:calc(12px + env(safe-area-inset-top,0px));left:14px;right:14px;bottom:auto;width:auto;max-width:560px;margin:0 auto;max-height:calc(100vh - 24px);max-height:calc(100dvh - 24px - env(safe-area-inset-top,0px));padding:16px 16px 20px;border:1.5px solid var(--red);border-radius:28px;background:#fff;box-shadow:var(--gp-glow);overflow-y:auto;overscroll-behavior:contain;transform-origin:50% 0;transform:scale(.86,.14);opacity:0;visibility:hidden;pointer-events:none;transition:transform .5s var(--ease),opacity .3s var(--ease),visibility 0s .5s}
body .nav-panel.is-open{transform:none;opacity:1;visibility:visible;pointer-events:auto;transition-delay:0s}
.nav-panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;padding-left:2px}
body .nav-panel-head .logo-img{height:34px}
body .nav-panel-close{position:static;width:38px;height:38px;border:0;background:transparent}
body .nav-panel-close svg{width:20px;height:20px;stroke:var(--ink-soft)}
body .nav-panel-close:hover{background:var(--red-soft);transform:none}
body .nav-panel-close:hover svg{stroke:var(--red)}
/* pill buttons grid */
body .nav-links-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:0}
body .nav-links-list li{display:contents;opacity:1;transform:none;transition:none}
body .nav-links-list li>a,body .nav-links-list .nav-sub-toggle{display:flex;align-items:center;justify-content:center;gap:6px;width:auto;min-height:52px;padding:10px 6px;border:1.5px solid var(--line);border-radius:18px;background:var(--paper-alt);font-family:var(--font-body);font-size:14px;font-weight:600;letter-spacing:0;text-transform:none;text-align:center;line-height:1.15;color:var(--ink);opacity:0;transform:translateY(10px) scale(.96);transition:opacity .3s var(--ease),transform .3s var(--ease),background .2s,border-color .2s,color .2s}
body .nav-panel.is-open .nav-links-list li>a,body .nav-panel.is-open .nav-links-list .nav-sub-toggle{opacity:1;transform:none;transition:opacity .4s var(--ease) calc(.12s + var(--i,0) * .045s),transform .4s var(--ease) calc(.12s + var(--i,0) * .045s),background .2s,border-color .2s,color .2s}
body .nav-links-list li>a:hover,body .nav-links-list .nav-sub-toggle:hover{border-color:var(--red);background:#fff}
body .nav-links-list li>a.is-active,body .nav-links-list .nav-sub-toggle.is-active,body .nav-sub.is-open .nav-sub-toggle{color:var(--red);border-color:var(--red);background:var(--red-soft)}
body .nav-sub-toggle svg{width:11px;height:11px}
/* services sub tray */
body .nav-sub-list{display:none;grid-column:1/-1;max-height:none;overflow:visible;margin:0;padding:10px;border:0;border-radius:20px;background:rgba(251,230,232,.55)}
body .nav-sub.is-open .nav-sub-list{display:grid;grid-template-columns:1fr 1fr;gap:8px;animation:gpNavSub .35s var(--ease)}
@keyframes gpNavSub{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
body .nav-links-list .nav-sub-list a{min-height:46px;padding:9px 8px;border-radius:14px;background:#fff;font-size:13px;color:var(--ink)}
body .nav-links-list .nav-sub-list li:first-child>a{grid-column:1/-1;background:var(--ink);border-color:var(--ink);color:#fff}
/* CTA + socials */
.nav-panel-cta{display:flex;align-items:center;justify-content:center;width:74%;margin:22px auto 0;padding:16px 20px;border-radius:100px;background:var(--red);color:#fff;font-size:16px;font-weight:600;box-shadow:0 12px 30px -8px rgba(226,35,58,.6);opacity:0;transform:translateY(12px);transition:opacity .3s var(--ease),transform .3s var(--ease)}
body .nav-panel.is-open .nav-panel-cta{opacity:1;transform:none;transition:opacity .45s var(--ease) .4s,transform .45s var(--ease) .4s}
body .nav-panel-socials{margin-top:20px;gap:10px;justify-content:flex-start}
body .nav-social,body .nav-social:hover{width:44px;height:44px;border:0;background:transparent;border-radius:0;overflow:visible}
body .nav-social::before{display:none}
body .nav-social svg,body .nav-social:hover svg{width:44px;height:44px;display:block;stroke:none}
}
@media (max-width:860px) and (prefers-reduced-motion:reduce){body .nav-panel,body .nav-links-list li>a,body .nav-links-list .nav-sub-toggle,.nav-panel-cta{transition:none!important}}`;
document.head.appendChild(st);
}
