/* =====================================================================
   CREATOR TOOLS — ONE LIST FOR BOTH THE POPUP AND THE CREATOR TOOLS PAGE
   Add a line per product:
     url  = your Amazon / Flipkart link (required)
     img  = direct image address (optional but most reliable)
     name = product name (optional; auto-fetched if left empty)
     note = one short line under the name (optional)
   The popup shows the first 10; the Creator Tools page shows all of them.
   ===================================================================== */
const CREATOR_PRODUCTS=[
{url:"https://www.amazon.in/s?k=led+ring+light+with+tripod+stand",img:"assets/tools/ring-light.png",name:"LED Ring Light with Tripod Stand",note:"Even, flattering light for videos and shoots."},
{url:"https://www.amazon.in/s?k=usb+condenser+podcast+microphone",img:"assets/tools/usb-mic.png",name:"USB Condenser Podcast Microphone",note:"Plug-and-play, studio-clear voice."},
{url:"https://www.amazon.in/s?k=foldable+photo+studio+light+box",img:"assets/tools/light-box.png",name:"Foldable Photo Studio Light Box",note:"Clean product photos at home."},
{url:"https://www.amazon.in/s?k=studio+monitor+headphones",img:"assets/tools/headphones.png",name:"Studio Monitor Headphones",note:"Accurate sound for editing and mixing."},
{url:"https://www.amazon.in/s?k=green+screen+backdrop+with+stand",img:"assets/tools/green-screen.png",name:"Green Screen Backdrop with Stand",note:"Swap backgrounds in seconds."},
{url:"https://www.flipkart.com/search?q=softbox+lighting+kit",img:"assets/tools/softbox.png",name:"Softbox Lighting Kit for Studio",note:"Soft, even light for portraits and products."},
{url:"https://www.flipkart.com/search?q=wireless+lavalier+mic",img:"assets/tools/lavalier-mic.png",name:"Wireless Lavalier Collar Mic",note:"Clip-on audio for reels and interviews."},
{url:"https://www.flipkart.com/search?q=camera+tripod+with+phone+holder",img:"assets/tools/tripod.png",name:"Camera Tripod with Phone Holder",note:"Steady shots, phone or camera."},
{url:"https://www.flipkart.com/search?q=mic+boom+arm+with+pop+filter",img:"assets/tools/boom-arm.png",name:"Mic Boom Arm with Pop Filter",note:"Keeps your mic positioned and plosives down."},
{url:"https://www.flipkart.com/search?q=acoustic+foam+panels",img:"assets/tools/acoustic-foam.png",name:"Acoustic Foam Panels (Pack of 12)",note:"Cut echo in your recording space."}
];
const GP_BAG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 8h12l-1 12H7L6 8z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg>';
function gpStore(u){try{const h=new URL(u).hostname.toLowerCase();if(/amazon|amzn/.test(h))return"Amazon";if(/flipkart|fkrt/.test(h))return"Flipkart"}catch(e){}return"Store"}
function gpShot(url){
  const key="gp_prod2_"+url;
  try{const c=JSON.parse(localStorage.getItem(key));if(c&&c.image)return Promise.resolve(c)}catch(e){}
  return fetch("https://api.microlink.io/?url="+encodeURIComponent(url))
    .then(r=>r.json())
    .then(j=>{const d=j&&j.data;if(!d||!d.image||!d.image.url)throw 0;const o={image:d.image.url,title:d.title||""};try{localStorage.setItem(key,JSON.stringify(o))}catch(e){}return o});
}
function gpLoadImg(box,p,alt,done,fail){
  const put=(src,retry)=>{
    const im=new Image();im.alt=alt||"";im.referrerPolicy="no-referrer";
    im.onload=()=>{box.classList.remove("is-loading");box.appendChild(im);done&&done()};
    im.onerror=()=>retry?retry():fail();
    im.src=src;
  };
  const auto=()=>gpShot(p.url).then(o=>{done&&done(o);put(o.image)},fail);
  p.img?put(p.img,auto):auto();
}
function initWelcomeProducts(){
  const go=document.getElementById("welcome-modal-dismiss");
  if(go)go.addEventListener("click",()=>{location.href="creator-tools.html"});
  const box=document.getElementById("welcome-products");
  if(!box)return;
  try{if(sessionStorage.getItem("gp_welcome_shown")==="1")return}catch(e){}
  Array.from({length:10},(_,i)=>CREATOR_PRODUCTS[i]).forEach((p,i)=>{
    if(!p||!p.url){const e=document.createElement("span");e.className="welcome-prod is-fallback";e.innerHTML=GP_BAG;box.appendChild(e);return}
    const a=document.createElement("a");
    a.className="welcome-prod is-loading";
    a.href=p.url;a.target="_blank";a.rel="noopener noreferrer sponsored";
    a.setAttribute("aria-label","View product "+(i+1));
    box.appendChild(a);
    gpLoadImg(a,p,"",null,()=>{a.classList.remove("is-loading");a.classList.add("is-fallback");a.innerHTML=GP_BAG});
  });
}
function initCreatorTools(){
  const grid=document.getElementById("ct-grid");
  if(!grid)return;
  const items=CREATOR_PRODUCTS.filter(p=>p&&p.url);
  const empty=document.getElementById("ct-empty"),filters=document.getElementById("ct-filters"),note=document.getElementById("ct-disclosure");
  if(!items.length){if(empty)empty.hidden=false;if(filters)filters.hidden=true;if(note)note.hidden=true;return}
  const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17L17 7M8 7h9v9"/></svg>';
  const cleanTitle=t=>(t||"").replace(/^(amazon\.in\s*:\s*)/i,"").replace(/\s*[|:-]\s*(buy|online).*$/i,"").slice(0,110).trim();
  const stores={};
  items.forEach(p=>{
    const store=gpStore(p.url);stores[store]=1;
    const card=document.createElement("article");
    card.className="ct-card";card.dataset.store=store;
    card.innerHTML='<a class="ct-media is-loading" tabindex="-1" aria-hidden="true"><span class="ct-store ct-store-'+store.toLowerCase()+'"></span></a><div class="ct-body"><h3 class="ct-name"></h3><p class="ct-note"></p><a class="ct-btn">See the Product '+arrow+'</a></div>';
    const media=card.querySelector(".ct-media"),nm=card.querySelector(".ct-name"),nt=card.querySelector(".ct-note"),btn=card.querySelector(".ct-btn");
    card.querySelector(".ct-store").textContent=store;
    [media,btn].forEach(a=>{a.href=p.url;a.target="_blank";a.rel="noopener noreferrer sponsored"});
    nm.textContent=p.name||"View on "+store;
    nt.textContent=p.note||"";
    btn.setAttribute("aria-label","See the product on "+store);
    gpLoadImg(media,p,p.name||"",o=>{if(!p.name&&o&&o.title)nm.textContent=cleanTitle(o.title)||nm.textContent},()=>{media.classList.remove("is-loading");media.classList.add("is-fallback");media.insertAdjacentHTML("beforeend",GP_BAG)});
    grid.appendChild(card);
  });
  if(filters){
    if(Object.keys(stores).length<2){filters.hidden=true}
    else filters.querySelectorAll(".ct-filter").forEach(b=>b.addEventListener("click",()=>{
      filters.querySelectorAll(".ct-filter").forEach(x=>x.classList.toggle("is-active",x===b));
      const f=b.dataset.filter;
      grid.querySelectorAll(".ct-card").forEach(c=>{c.hidden=f!=="all"&&c.dataset.store!==f});
    }));
  }
}
function initNavDropdown(){
  document.querySelectorAll(".nav-sub-toggle").forEach(b=>b.addEventListener("click",()=>{
    const li=b.closest(".nav-sub"),o=li.classList.toggle("is-open");
    b.setAttribute("aria-expanded",o);
  }));
}